import type { ToolRunner } from "@bithumb-official/bithumb-core";
import { BithumbApiError } from "@bithumb-official/bithumb-core";
import type { CliValues } from "../parser.js";
import { toNumber, toArray, parseJsonStringArray, parseRangedInt, parsePositiveInt, parseEnumString } from "../parser.js";
import { outputLine, errorLine, printJson, printTable, printKv } from "../formatter.js";

// Valid --state values per endpoint (case-sensitive). KRW deposits use a short
// lifecycle; coin deposits expose a 15-value compound state machine covering
// request / deposit / refund-request / refund-payout phases.
const DEPOSIT_KRW_STATES = ["PROCESSING", "ACCEPTED", "CANCELLED"] as const;
const DEPOSIT_COIN_STATES = [
  "REQUESTED_PENDING",
  "REQUESTED_SYSTEM_REJECTED",
  "REQUESTED_PROCESSING",
  "REQUESTED_ADMIN_REJECTED",
  "DEPOSIT_PROCESSING",
  "DEPOSIT_ACCEPTED",
  "DEPOSIT_CANCELLED",
  "REFUNDING_PENDING",
  "REFUNDING_SYSTEM_REJECTED",
  "REFUNDING_PROCESSING",
  "REFUNDING_ADMIN_REJECTED",
  "REFUNDING_ACCEPTED",
  "REFUNDED_PROCESSING",
  "REFUNDED_ACCEPTED",
  "REFUNDED_CANCELLED",
] as const;

export async function handleDepositCommand(
  run: ToolRunner,
  action: string,
  v: CliValues,
  json: boolean,
): Promise<void> {
  switch (action) {
    case "get":
      return cmdGet(run, v, json);
    case "list":
      return cmdList(run, v, json);
    case "list-krw":
      return cmdListKrw(run, v, json);
    case "krw":
      return cmdKrw(run, v, json);
    case "generate-address":
      return cmdGenerateAddress(run, v, json);
    case "addresses":
      return cmdAddresses(run, json);
    case "address":
      return cmdAddress(run, v, json);
    default:
      errorLine(`Unknown deposit command: ${action}. Run 'bithumb deposit --help' for usage.`);
      process.exitCode = 1;
  }
}

async function cmdGet(run: ToolRunner, v: CliValues, json: boolean): Promise<void> {
  if (!v.currency) {
    errorLine("Error: --currency required. Example: bithumb deposit get --currency BTC --deposit-id abc-123");
    process.exitCode = 1;
    return;
  }
  // Per Bithumb GET /v1/deposit, only `currency` is required; deposit_id and
  // txid are both optional and may be combined (the API treats them as an AND
  // filter). Omitting both returns the most recent deposit.
  const args: Record<string, unknown> = { currency: v.currency };
  if (v.depositId) args.deposit_id = v.depositId;
  if (v.txid) args.txid = v.txid;
  try {
    const result = await run("deposit_get", args);
    const data = result.data as Record<string, unknown> | undefined;
    if (!data || (typeof data === "object" && Object.keys(data).length === 0)) {
      outputLine("No deposit found.");
      return;
    }
    if (json) return printJson(data);
    // Relabel the response's legacy `uuid` field as `deposit_id` for display
    // consistency with the input flag. Raw JSON (--json) keeps the original field.
    printKv(renameKey(data, "uuid", "deposit_id"));
  } catch (err) {
    // Bithumb API may return 4xx for unknown UUID; render gracefully without the `Fatal:` prefix.
    if (err instanceof BithumbApiError) {
      const codeNum = Number(err.code);
      const codeStr = err.code ?? "";
      const errNamePattern = /not.?found|invalid|forbidden|unauthorized|bad.?request/i;
      const messagePattern = /not.?found|invalid/i;
      const isClientError =
        (Number.isFinite(codeNum) && codeNum >= 400 && codeNum < 500) ||
        errNamePattern.test(codeStr) ||
        messagePattern.test(err.message);
      if (isClientError) {
        errorLine(`Error: deposit not found or invalid request (${err.code}). ${err.message}`);
        process.exitCode = 1;
        return;
      }
      // Other Bithumb API errors (5xx, unknown code): still graceful, not Fatal.
      errorLine(`Error: ${err.message}`);
      process.exitCode = 1;
      return;
    }
    throw err;
  }
}

async function cmdList(run: ToolRunner, v: CliValues, json: boolean): Promise<void> {
  const args: Record<string, unknown> = {};
  if (v.currency) args.currency = v.currency;
  if (v.state) args.state = parseEnumString("state", v.state, DEPOSIT_COIN_STATES);
  if (v.depositIds) args.deposit_ids = toArray(v.depositIds);
  if (v.txids) args.txids = parseJsonStringArray("txids", v.txids);
  if (v.limit) args.limit = parseRangedInt("limit", toNumber(v.limit, "limit"), 1, 100);
  if (v.page) args.page = parsePositiveInt("page", toNumber(v.page, "page"));
  if (v.orderBy) args.order_by = v.orderBy;
  const result = await run("deposit_get_list", args);
  const items = result.data as Record<string, unknown>[];
  if (json) return printJson(items);
  if (!items?.length) { outputLine("No deposits found"); return; }
  printTable(items.map((o) => renameKey(o, "uuid", "deposit_id")));
}

async function cmdListKrw(run: ToolRunner, v: CliValues, json: boolean): Promise<void> {
  const args: Record<string, unknown> = {};
  if (v.state) args.state = parseEnumString("state", v.state, DEPOSIT_KRW_STATES);
  if (v.depositIds) args.deposit_ids = toArray(v.depositIds);
  if (v.txids) args.txids = parseJsonStringArray("txids", v.txids);
  if (v.limit) args.limit = parseRangedInt("limit", toNumber(v.limit, "limit"), 1, 100);
  if (v.page) args.page = parsePositiveInt("page", toNumber(v.page, "page"));
  if (v.orderBy) args.order_by = v.orderBy;
  const result = await run("deposit_get_list_krw", args);
  const items = result.data as Record<string, unknown>[];
  if (json) return printJson(items);
  if (!items?.length) { outputLine("No KRW deposits found"); return; }
  printTable(items.map((o) => renameKey(o, "uuid", "deposit_id")));
}

// Return a shallow copy of `obj` with key `from` renamed to `to`, preserving
// insertion order. If `from` is absent, returns the object unchanged.
function renameKey(
  obj: Record<string, unknown>,
  from: string,
  to: string,
): Record<string, unknown> {
  if (!(from in obj)) return obj;
  const out: Record<string, unknown> = {};
  for (const [k, val] of Object.entries(obj)) {
    out[k === from ? to : k] = val;
  }
  return out;
}

async function cmdKrw(run: ToolRunner, v: CliValues, json: boolean): Promise<void> {
  if (!v.amount || !v.twoFactorType) {
    errorLine("Error: --amount and --two-factor-type required.");
    errorLine("CAUTION: This will initiate a real KRW deposit request!");
    process.exitCode = 1;
    return;
  }
  const result = await run("deposit_krw", { amount: v.amount, two_factor_type: v.twoFactorType });
  const data = result.data as Record<string, unknown>;
  if (json) return printJson(data);
  printKv(data);
}

async function cmdGenerateAddress(run: ToolRunner, v: CliValues, json: boolean): Promise<void> {
  if (!v.currency || !v.netType) {
    errorLine("Error: --currency and --net-type required. Example: bithumb deposit generate-address --currency BTC --net-type BTC");
    process.exitCode = 1;
    return;
  }
  const result = await run("deposit_generate_address", { currency: v.currency, net_type: v.netType });
  const data = result.data as Record<string, unknown>;
  if (json) return printJson(data);
  printKv(data);
}

async function cmdAddresses(run: ToolRunner, json: boolean): Promise<void> {
  const result = await run("deposit_get_addresses", {});
  const items = result.data as Record<string, unknown>[];
  if (json) return printJson(items);
  if (!items?.length) { outputLine("No deposit addresses found"); return; }
  printTable(items);
}

async function cmdAddress(run: ToolRunner, v: CliValues, json: boolean): Promise<void> {
  if (!v.currency || !v.netType) {
    errorLine("Error: --currency and --net-type required. Example: bithumb deposit address --currency BTC --net-type BTC");
    process.exitCode = 1;
    return;
  }
  const result = await run("deposit_get_address", { currency: v.currency, net_type: v.netType });
  const data = result.data as Record<string, unknown>;
  if (json) return printJson(data);
  printKv(data);
}
